"""Interaction functions for the Radiation Prescription (Rad Rx) window UI in the Mosaiq application.
This window is displayed by selecting the Rad Rx button from the D and I window"""

from .objects.mosaiq_d_and_i_objects import DandI
from . d_and_i import clear_text_box
import interops.libraries.desktop.decorators as deco
from interops.libraries.squish_actions.constants import MOSAIQ_APP_NAME
from interops.libraries.squish_actions import CommonActions


def __find_rad_rx_window() -> bool:
    """Searches for the Rad Rx window within the D and I workflow. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the d_and_i.py file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(DandI.radRX_Main_Window) is not None else False


@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_rad_rx_change_button() -> None:
    """Locates the main D and I UI window > clicks the Rad Rx button > then waits for the Rad Rx window to appear.
    """
    if __find_rad_rx_window():
        CommonActions.left_click_object(DandI.radRX_Change_Button)


@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def type_in_rx_site_text_field(rxSite: str) -> None:
    """Locates the D and I - Rad Rx main window > then types the given rxSite into the Rx Site text field.

    :param str rxSite: Given Rx Site as a string variable to be typed into the Rx Site text field of the Rad Rx UI.
    """
    if __find_rad_rx_window():
        clear_text_box(DandI.radRX_Rx_Site_Textbox)
        CommonActions.type_in_textfield(DandI.radRX_Rx_Site_Textbox, rxSite)


@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_rad_rx_ok_button() -> None:
    """Locates the D and I - Rad Rx main window > then clicks the OK button.
    """
    if __find_rad_rx_window():
        CommonActions.left_click_object(DandI.radRX_OK_Button)


@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_rad_rx_close_button() -> None:
    """Locates the D and I - Rad Rx main window > then clicks the Close button.
    """
    if __find_rad_rx_window():
        CommonActions.left_click_object(DandI.radRX_Close_Button)


@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def toggle_rad_rx_adaptive_checkbox(enableCheckbox: bool = True) -> None:
    """Locates the D and I - Rad Rx main window > then toggles (checked/unchecked) the Adaptive Checkbox.
    """
    if __find_rad_rx_window():
        if enableCheckbox:
            if not CommonActions.get_checkbox_state(DandI.radRx_Adaptive_Checkbox):
                CommonActions.left_click_object_no_move(DandI.radRx_Adaptive_Checkbox)
        else:
            if CommonActions.get_checkbox_state(DandI.radRx_Adaptive_Checkbox):
                CommonActions.left_click_object_no_move(DandI.radRx_Adaptive_Checkbox)


@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_rad_rx_fractionation_pattern_dropdown() -> None:
    """Locates the D and I - Rad Rx main window > then clicks the Fractionation Pattern dropdown.
    """
    if __find_rad_rx_window():
        CommonActions.left_click_object(DandI.radRX_Fractionation_Pattern_Dropdown_Button)
        CommonActions.find_object(DandI.waveSetup_Form_Window)


@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_rad_rx_wave_setup_form_ok_button() -> None:
    """Locates the D and I - Rad Rx - Wave Setup Form window > then clicks the OK button.
    """
    CommonActions.find_object(DandI.waveSetup_Form_Window)
    CommonActions.left_click_object(DandI.waveSetup_Form_OK_Button)